2.query:
fetch spans, scanLimitGBytes:500
| filter contains(lower(url.path), lower($EndpointPattern))
| filter span.kind == "server"
| summarize {
    trafficCount = count(),
    lastSeen = takeMax(start_time),
    latestTraceId = takeFirst(trace.id)
  }, by: { url.path }
| sort lastSeen desc
| limit 500
